inline std::string_view electricityNoticeMessageKeyName(ElectricityNoticeMessageKey key){
    static constexpr std::array<std::string_view,electricityNoticeMessageKeyCount> names={{"electricity.notice.input_too_long","electricity.notice.non_ascii","electricity.notice.saved","electricity.notice.save_failed","electricity.notice.stamped_now","electricity.notice.rejected_input","electricity.notice.invalid_label","electricity.notice.invalid_currency","electricity.notice.invalid_rate","electricity.notice.invalid_integer","electricity.notice.invalid_interval","electricity.notice.invalid_offset"}};
    const auto index=static_cast<std::size_t>(key);return index<names.size()?names[index]:std::string_view{};
}
inline LocalizedMessage electricityNoticeMessage(std::string_view language,ElectricityNoticeMessageKey key){
    const auto index=static_cast<std::size_t>(key);if(index>=electricityNoticeMessageKeyCount)return {};
    const auto &source=electricityNoticeLocalePacks()[0];const auto *selected=&source;for(const auto &pack:electricityNoticeLocalePacks())if(pack.id==language){selected=&pack;break;}
    if(selected->id!=language||!validTemplateTranslation(source.messages[index],selected->messages[index]))return {source.messages[index],source.id,source.review,true,false};
    return {selected->messages[index],selected->id,selected->review,false,selected->rtl};
}
inline std::string electricityNoticeEnglish(ElectricityNoticeMessageKey key){return std::string(electricityNoticeMessage("en",key).text);}
